import { describe, it, expect } from 'vitest';
import { Spc700Dsp, REG, V } from '../spc700-dsp.js';

/**
 * Expected noise values below are hand-computed from the real feedback
 * formula transcribed in `spc700-dsp.ts`'s module doc comment (ported from
 * blargg's `snes_spc`, `~/Development/snes_spc/snes_spc/SPC_DSP.cpp`'s
 * `misc_30`/`voice_V3c`) -- not generated by running this implementation
 * and copying its output.
 */
describe('Spc700Dsp noise (NON)', () => {
  it('LFSR feedback sequence from the real reset value (0x4000) matches hand-computed values, observed via OUTX', () => {
    const ram = new Uint8Array(0x10000);
    // One-block BRR sample, looped on itself (header 0x03: shift=0,filter=0,loop=1,end=1), placed at
    // $0300 -- content is irrelevant, NON overrides the decoded sample value entirely; it only needs
    // to be a valid, indefinitely-looping block so the voice never stops "playing" mid-test.
    ram.set([0x03, 0, 0, 0, 0, 0, 0, 0, 0], 0x0300);
    // DIR page $02 (DIR reg = 0x02 -> dirAddr = $0200), srcn 0 -> entry at $0200: start=loop=$0300.
    ram.set([0x00, 0x03, 0x00, 0x03], 0x0200);

    const dsp = new Spc700Dsp(ram);
    dsp.write(REG.DIR, 0x02);
    dsp.write(REG.FLG, 0x1f); // noise rate = fastest (period 1, ENVELOPE_RATE_PERIOD[0x1f]) -- updates every step()
    dsp.write(REG.MVOLL, 127);
    dsp.write(REG.MVOLR, 127);
    dsp.write(REG.NON, 0x01); // voice 0 uses noise
    dsp.write(V.SRCN, 0); // voice 0 base offset is 0
    dsp.write(V.ADSR0, 0x00); // ADSR1 bit7 clear -> GAIN direct mode
    dsp.write(V.GAIN, 0x7f); // direct near-full envelope
    dsp.write(V.PITCHL, 0x00);
    dsp.write(V.PITCHH, 0x10); // pitch = 0x1000 = unity step
    dsp.write(REG.KON, 0x01); // key on voice 0 -- edge-detected and consumed on the very next step()

    // Hand-computed: noise starts at the real reset value 0x4000; feedback = (noise<<13)^(noise<<14);
    // noise = (feedback & 0x4000) ^ (noise>>1). OUTX = round(((int16_t)(noise*2))/32768 * 127) & 0xff,
    // with direct GAIN making OUTX depend on no other envelope state.
    const expectedOutx = [63, 32, 16, 8, 4, 2, 1, 0];

    for (let i = 0; i < expectedOutx.length; i++) {
      dsp.step();
      expect(dsp.read(V.OUTX)).toBe(expectedOutx[i]);
    }
  });

  it('a voice without its NON bit set is unaffected by noise (plays its real BRR content, not overridden)', () => {
    const ram = new Uint8Array(0x10000);
    // Same one-block loop, but with real non-zero decoded content this time (all data nibbles 0x77 ->
    // a strong non-zero constant residual) so a would-be noise override is trivially distinguishable.
    ram.set([0x03, 0x77, 0x77, 0x77, 0x77, 0x77, 0x77, 0x77, 0x77], 0x0300);
    ram.set([0x00, 0x03, 0x00, 0x03], 0x0200);

    const dsp = new Spc700Dsp(ram);
    dsp.write(REG.DIR, 0x02);
    dsp.write(REG.FLG, 0x1f);
    dsp.write(REG.MVOLL, 127);
    dsp.write(REG.MVOLR, 127);
    dsp.write(REG.NON, 0x00); // NOT set for voice 0
    dsp.write(V.SRCN, 0);
    dsp.write(V.ADSR0, 0x00);
    dsp.write(V.PITCHL, 0x00);
    dsp.write(V.PITCHH, 0x10);
    dsp.write(REG.KON, 0x01);

    dsp.step();
    // Noise's own OUTX for this same first update is 64 (per the hand-computed sequence above) --
    // asserting inequality (not a specific real-BRR-content value, which this test doesn't need to
    // hand-derive) is enough to prove the substitution didn't happen.
    expect(dsp.read(V.OUTX)).not.toBe(64);
  });
});

describe('Spc700Dsp pitch modulation (PMON)', () => {
  function createDsp(pmon: number): Spc700Dsp {
    const ram = new Uint8Array(0x10000);
    // A looped non-zero BRR block gives voice 0 a stable modulation source;
    // voice 1 uses a higher pitch so the modulated position is observable.
    ram.set([0xc3, 0x17, 0x7f, 0x81, 0xf7, 0x3f, 0xc1, 0x19, 0xe7], 0x0300);
    ram.set([0x00, 0x03, 0x00, 0x03], 0x0200);
    const dsp = new Spc700Dsp(ram);
    dsp.write(REG.DIR, 0x02);
    dsp.write(REG.MVOLL, 127);
    dsp.write(REG.MVOLR, 127);
    dsp.write(REG.PMON, pmon);
    for (let voice = 0; voice < 2; voice++) {
      const base = voice * 0x10;
      dsp.write(base + V.SRCN, 0);
      dsp.write(base + V.ADSR0, 0x00); // direct GAIN mode
      dsp.write(base + V.GAIN, 0x7f); // direct near-full envelope
      dsp.write(base + V.PITCHL, voice === 0 ? 0x00 : 0x00);
      dsp.write(base + V.PITCHH, voice === 0 ? 0x10 : 0x20);
      dsp.write(base + V.VOLL, 127);
      dsp.write(base + V.VOLR, 127);
    }
    dsp.write(REG.KON, 0x03);
    return dsp;
  }

  it('changes the modulated voice output when PMON uses the preceding voice sample', () => {
    const plain = createDsp(0);
    const modulated = createDsp(0x02); // voice 1 only
    const plainSamples: number[] = [];
    const modulatedSamples: number[] = [];
    for (let i = 0; i < 8; i++) {
      plain.step();
      modulated.step();
      plainSamples.push(plain.read(0x10 + V.OUTX));
      modulatedSamples.push(modulated.read(0x10 + V.OUTX));
    }
    expect(modulatedSamples).not.toEqual(plainSamples);
    expect(modulatedSamples.some((sample, i) => sample !== plainSamples[i])).toBe(true);
  });

  it('does not modulate voice 0 because it has no preceding voice', () => {
    const plain = createDsp(0);
    const pmonVoice0 = createDsp(0x01);
    for (let i = 0; i < 8; i++) {
      plain.step();
      pmonVoice0.step();
      expect(pmonVoice0.read(V.OUTX)).toBe(plain.read(V.OUTX));
    }
  });
});
